1.7.3 MySQL Command Line — Essential Operations

# Connect to MySQL as root (enter password when prompted):
mysql -u root -p

# List all databases:
SHOW DATABASES;

# Select a database to work with:
USE bob_wordpress;

# List all tables in the current database:
SHOW TABLES;

# View structure of a table:
DESCRIBE wp_options;

# Create a database:
CREATE DATABASE bob_newsite;

# Create a user and grant privileges:
CREATE USER 'bob_newuser'@'localhost' IDENTIFIED BY 'StrongPassword123!';
GRANT ALL PRIVILEGES ON bob_newsite.* TO 'bob_newuser'@'localhost';
FLUSH PRIVILEGES;

